namespace Fanex.Age.UI.Forecast
{

    public partial class ScoreMap_Page : Fanex.Age.UI.TplPage
    {
        #region Const
        private const String RUNNING_LEAGUES = "RunningLeague";        
        #endregion

        #region Variable
        private ScoreMap_Template tpl = new ScoreMap_Template();
        private int _leagueId = 0;
        private string _matchIds = string.Empty, _bettypes_live = string.Empty, _bettypes_dead = string.Empty;
        DataSet dsScoreMap = null;
        DataTable liveBallDeadBall = null;
        #endregion

        #region Override
        /// <summary>
        /// 
        /// </summary>
        /// <param name="writer"></param>
        public override void RenderContent(HtmlTextWriter writer)
        {
            if (UserSession.Current.Language == "vi-VN")
            {
                tpl.Content.LimitLeagueList.lblDeadball = "Dead Ball";
                tpl.Content.LimitLeagueList.lblLiveBall = "Live Ball";
            }
            else
            {
                tpl.Content.LimitLeagueList.lblDeadball = Resources.Lang.lblDeadball;
                tpl.Content.LimitLeagueList.lblLiveBall = Resources.Lang.lblLiveBall;
            }

            // Create Box Select Match
            MatchByLeague_Template tplMatch = new MatchByLeague_Template();
            
            tplMatch.MatchIds = _matchIds;
            tpl.BoxMatch = tplMatch;

            RegisterJavascriptObject("FilterMatch", "");
            RegisterJavascriptObject("selectMatch", Resources.Lang.SelectMatch);
            RegisterJavascriptObject("hideMatch", Resources.Lang.hideMatch);
            RegisterJavascriptObject("noInfo", Resources.Lang.noInfo);
            RegisterJavascriptObject("plsChooseBetType", Resources.Lang.plsChooseBetType);
            RegisterJavascriptObject("plsChooseMatch", Resources.Lang.plsChooseMatch);

            // Header name
            RenderLeagueList(tpl.Content);

            if (CurrentUserSession.Language == "th-TH" || CurrentUserSession.Language == "ja-JP")
            {
                tpl.Content.LimitLeagueList.mWidth = "1030px";
                tpl.Content.mWidth = "1030px";
            }
            else
            {
                tpl.Content.LimitLeagueList.mWidth = "1000px";
                tpl.Content.mWidth = "99%";
            }

            if (_leagueId != -1)
            {
                tpl.mainTitle.Forecast = Resources.Lang.lblScoreMap;
                tpl.Content.LimitLeagueList.display = "";
                tpl.Content.LimitLeagueList.displayLiveDead = "display:none";
                tpl.Content.ScoreMap = null;
            }
            else
            {
                tpl.mainTitle = null;
                tpl.Content.LimitLeagueList.display = "display:none";
                tpl.Content.LimitLeagueList.displayLiveDead = "";

                StringBuilder content = new StringBuilder();
                DataTable listScoreMap = dsScoreMap.Tables[0];
                DataTable listMatch = dsScoreMap.Tables[1];
                RenderingFactory.Render(false, listScoreMap, listMatch, content, false);
                tpl.Content.ScoreMap.SetValue(content.ToString());
            }

            writer.Write(tpl);
        }

        public override void ProcessRequest(ref System.Collections.Hashtable p)
        {
            p.AddHttpParameters(new string[] { 
                "leagueId", "bettypes_live", "bettypes_dead"
            }, Request);
            _leagueId = Convert.ToInt32(p["leagueId"]);
            _matchIds = string.IsNullOrEmpty(Request["matchIds"]) ? "-1" : Request["matchIds"].ToString();
            _bettypes_live = Convert.ToString(p["bettypes_live"]);
            _bettypes_dead = Convert.ToString(p["bettypes_dead"]);
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            Dictionary<String, DataTable> view = new Dictionary<string, DataTable>();
            ForecastBO bo = new ForecastBO(CurrentUserSession.NetSessionId);

            DataTable runningLeagues = null;
            if (_leagueId != -1) // -1: Link from BetList
            {
                runningLeagues = bo.GetLeagueScoreMap();
            }

            // Create resource and set "_bettypes_live/_bettypes_dead" when link from betlist.
            liveBallDeadBall = bo.GetBetTypeScoreMap();
            RenderLiveBallDeadBall(tpl.Content);

            if (_matchIds != "-1")
            {
                dsScoreMap = bo.GetScoreMapResult(_matchIds, _bettypes_live, _bettypes_dead);
            }

            view.Add(RUNNING_LEAGUES, runningLeagues);
            return view;
        }
        #endregion

        #region Render Utility
        private void RenderLeagueList(ScoreMap_Content_Block content)
        {
            DataTable leagues = (View as Dictionary<String, DataTable>)[RUNNING_LEAGUES];
            if (leagues != null && leagues.Rows.Count > 0)
            {
                RefreshLeague cs = new RefreshLeague();
                content.LimitLeagueList.LeagueList = cs.RenderLeagueList(leagues, _leagueId);
            }
            else
            {
                if (_leagueId!=-1) 
                    content.SetValue("<div class='no_info'>" + Resources.Lang.noInfo + "</div>");
                else
                    content.LimitLeagueList.LeagueList = "<option value='0'></option>";
            }
        }

        private void RenderLiveBallDeadBall(ScoreMap_Content_Block content)
        {
            int Count = liveBallDeadBall.Rows.Count;
            int AvgCount = Count/2;
            if (liveBallDeadBall != null && Count > 0)
            {
                Boolean isCheckAllLiveBall = true, isCheckAllDeadBall = true;
                int indexLiveBall = 1, indexDeadBall = 1;
                int typeId = 0;
                string stId = string.Empty;
                string[] stIdArray;
                char[] splitChars = new char[] { ',' };
                BoxLiveBallDeadBall_Template tplLBDB;
                StringBuilder liveBall = new StringBuilder();
                StringBuilder deadBall = new StringBuilder();
                
                foreach (DataRow dr in liveBallDeadBall.Rows)
                {
                    tplLBDB = new BoxLiveBallDeadBall_Template();
                    typeId = Convert.ToInt32(dr["typeid"]);
                    stId = Convert.ToString(dr["1stId"]);
                    stIdArray = stId.Split(splitChars, StringSplitOptions.RemoveEmptyEntries);
                    tplLBDB.BetType = typeId + (stId != "0" ? "," + stId : string.Empty);
                    tplLBDB.BetTypeName = GetBetTypeName(typeId);
                    tplLBDB.Title = GetTitleName(typeId);

                    if (Convert.ToBoolean(dr["islive"]))
                    {
                        tplLBDB.LiveDead = "L";
                        if (string.IsNullOrEmpty(_bettypes_live) || _bettypes_live == typeId.ToString() || stIdArray.Contains(_bettypes_live)) 
                        {
                            if (!string.IsNullOrEmpty(_bettypes_live) && typeId != 0 && stId != "0")
                            {
                                _bettypes_live = typeId.ToString() + "," + stId;
                            }

                            tplLBDB.isChecked = "checked";
                        }
                        else
                        {
                            tplLBDB.isChecked = "";
                            isCheckAllLiveBall = false;
                        }

                        if (indexLiveBall > AvgCount)
                        {
                            tplLBDB.mClass = "class='TLiveDead'";
                        }
                        else
                        {
                            tplLBDB.mClass = string.Empty;
                        }

                        liveBall.Append(tplLBDB);
                        
                        if (indexLiveBall == AvgCount)
                        {
                            if (Count % indexLiveBall != 0)
                                liveBall.Append("<td class='TLiveDead'></td></tr><tr>");
                            else
                                liveBall.Append("</tr><tr>");
                        }
                        indexLiveBall++;
                    }
                    if (Convert.ToBoolean(dr["isdead"]))
                    {
                        tplLBDB.LiveDead = "D";
                        if (string.IsNullOrEmpty(_bettypes_dead) || _bettypes_dead == typeId.ToString() || stIdArray.Contains(_bettypes_dead))
                        {
                            if (!string.IsNullOrEmpty(_bettypes_dead) && typeId != 0 && stId != "0")
                            {
                                _bettypes_dead = typeId.ToString() + "," + stId;
                            }

                            tplLBDB.isChecked = "checked";
                        }
                        else
                        {
                            tplLBDB.isChecked = "";
                            isCheckAllDeadBall = false;
                        }
                        if (indexDeadBall > AvgCount)
                        {
                            tplLBDB.mClass = "class='TLiveDead'";
                        }
                        else
                        {
                            tplLBDB.mClass = string.Empty;
                        }
                        deadBall.Append(tplLBDB);
                        
                        if (indexDeadBall == AvgCount)
                        {
                            if (Count % indexDeadBall != 0)
                                deadBall.Append("<td></td></tr><tr>");
                            else
                                deadBall.Append("</tr><tr>");
                        }
                        indexDeadBall++;
                    }
                }
                
                liveBall.Append("<td class='TLiveDead'></td>");

                tpl.Content.LimitLeagueList.isCheckedAllLive = isCheckAllLiveBall ? "checked" : "";
                tpl.Content.LimitLeagueList.isCheckedAllDead = isCheckAllDeadBall ? "checked" : "";
                content.LimitLeagueList.LiveBall = liveBall.ToString();
                content.LimitLeagueList.DeadBall = deadBall.ToString();
            }
            else
            {
                content.LimitLeagueList.Hide();
            }
        }

        private string GetBetTypeName(int typeid)
        {
            switch (typeid)
            {
                case 5: return Resources.Lang.lbl1x2;
                default: return CacheRef.GetBettype(typeid);
            }
        }

        private string GetTitleName(int typeid)
        {
            switch (typeid)
            {
                case 1: return Resources.Lang.lblHandicapFC;
                case 2: return Resources.Lang.lblOddEven;
                case 3: return Resources.Lang.lblOverUnder;
                case 4: return Resources.Lang.correctscore;
                case 5: return Resources.Lang.lbl1x2;
                case 6: return Resources.Lang.totalgoal;
                case 20: return Resources.Lang.moneyline;
                case 123: return Resources.Lang.lblDraw + " &#92 " + Resources.Lang.lblNoDraw;
                default: return string.Empty;
            }
        }
        #endregion
    }
}
